    {
      "source": "farmington/final_permit.pdf",
      "locator": "Page 26, Section part_i",
      "exact_span": "A summary of all monitoring activities performed within the\nprevious 12 months. The following information shall be reported:",
      "affected_purpose": "B,C",
      "computation_change_reason": "The 12-month monitoring-activity summary is direct evidence of what monitoring was performed; interpreting the scope or completeness of this summary affects whether monitoring was required, was performed, or lacks adequate evidence."
