      "source": "farmington/final_permit.pdf",
      "locator": "Page 26, Section part_i",
      "exact_span": "total number of inspections performed;",
      "affected_purpose": "B,C",
      "computation_change_reason": "Inspection counts are a distinct monitoring-activity type; whether inspections satisfy or substitute for sampling or other required monitoring depends on how this reported activity is interpreted against permit monitoring obligations."
    },
    {
      "source": "farmington/final_permit.pdf",
      "locator": "Page 26, Section part_i",
      "exact_span": "total number of sampling visits made;",
      "affected_purpose": "B,C",
      "computation_change_reason": "Sampling-visit counts bear on whether required sampling occurred; different interpretations of what constitutes a sampling visit or whether reported visits meet the obligation change monitoring-applicability and missing-evidence conclusions."
    },
    {
      "source": "farmington/final_permit.pdf",
      "locator": "Page 26, Section part_i",
      "exact_span": "Status of compliance with both effluent limitations and reporting\nrequirements.",
      "affected_purpose": "A,B",
      "computation_change_reason": "Coupling effluent-limitation compliance with reporting-requirement compliance means a different reading of either limb can change limit-exceedance evaluation (A) and whether monitoring/reporting obligations were met (B)."
