    {
      "source": "farmington/final_permit.pdf",
      "locator": "Page 26, Section part_i",
      "exact_span": "Compliant (C) - no violations during the previous 12 month\nperiod;",
      "affected_purpose": "A,C",
      "computation_change_reason": "The compliant status hinges on what counts as a violation over the prior 12 months; interpreting violations differently changes whether measurements are treated as within limits and how no-result or missing-evidence periods are classified."
    },
    {
      "source": "farmington/final_permit.pdf",
      "locator": "Page 26, Section part_i",
      "exact_span": "Non-compliant (NC) - one or more violations during the\nprevious 12 months but does not meet the criteria for significantly noncompliant industrial users;",
      "affected_purpose": "A,C",
      "computation_change_reason": "The NC threshold depends on counting violations and distinguishing them from significant noncompliance; alternative readings of violation count or severity change compliance classification and missing-evidence semantics."
    },
    {
      "source": "farmington/final_permit.pdf",
      "locator": "Page 26, Section part_i",
      "exact_span": "Significant Noncompliance (SN) - in accordance with\nrequirements described in d. above;",
      "affected_purpose": "A,B,C",
      "computation_change_reason": "SN status is defined by criteria referenced outside this segment ('d. above'); without resolving that cross-reference, interpretations of which users are significantly noncompliant—and thus subject to heightened reporting and enforcement consequences—remain open and can change all three computations."
    },
    {
      "source": "farmington/final_permit.pdf",
      "locator": "Page 26, Section part_i",
      "exact_span": "For significantly noncompliant industrial users, indicate the nature\nof the violations, the type and number of actions taken (notice of violation, administrative order,\ncriminal or civil suit, fines or penalties collected, etc.) and current compliance status.",
      "affected_purpose": "A,C",
      "computation_change_reason": "The nature of violations and subsequent enforcement actions inform whether effluent-limit exceedances are established and how current compliance status should be read when ordinary numeric results or complete monitoring records are absent."
    },
    {
      "source": "farmington/final_permit.pdf",
      "locator": "Page 26, Section part_i",
      "exact_span": "If ANY",
      "affected_purpose": "C",
      "computation_change_reason": "This segment ends with an incomplete conditional ('If ANY'); the missing predicate leaves unresolved what additional reporting or compliance consequence follows, affecting how missing-evidence cases at the boundary of significant noncompliance should be classified."
    }
  ]
